	id := c.create("tok-ana", `{"text":"water plants","in":"1h"}`)
	if code := c.do("tok-ana", http.MethodPost, "/v1/reminders/"+id+"/snooze", `{"for":"2h"}`, nil); code != http.StatusNoContent {
